import re
src=open('client/src/pages/trades/trades-terminal.tsx').read()
tp=src[src.index('export const TP_TERM_CSS = `'):]
tp=tp[:tp.index('\n`;')] if '\n`;' in tp else tp
scoped=open('client/src/features/terminal/trades/trades-terminal-view.css').read()
def rules(t, strip=None):
    d={}
    for m in re.finditer(r'(\.[a-zA-Z0-9_.\- >]+?)\s*\{([^}]*)\}', t):
        sel=m.group(1).strip()
        if strip: sel=sel.replace(strip,'').strip()
        d.setdefault(sel, m.group(2).strip())
    return d
a=rules(tp); b=rules(scoped,'.trades-terminal-view')
same=diff=0; examples=[]
for k,v in a.items():
    if k in b:
        va=re.sub(r'\s+',' ',v); vb=re.sub(r'\s+',' ',b[k])
        va=re.sub(r'\$\{[A-Z]+\}','#',va)
        if va==vb: same+=1
        else:
            diff+=1
            if len(examples)<4: examples.append((k,va[:90],vb[:90]))
print(f"selectors in TP_TERM_CSS: {len(a)}  |  identical to scoped: {same}  |  differing: {diff}")
for k,x,y in examples: print("\n DIFF",k,"\n   TP_TERM_CSS:",x,"\n   scoped     :",y)
PY

